import React, { useState } from "react";
import axios from "axios";
import { ShieldAlert, ShieldCheck } from "lucide-react";

const ThreatLab = () => {
  const [status, setStatus] = useState(null);
  const [logs, setLogs] = useState([]);

  const run = async (type) => {
    setLogs([]);
    setStatus("running");

    try {
      const res = await axios.post(
  "http://localhost:8000/simulate/attack?attack=" + type
);


      setLogs([
        res.data.attack_info,
        res.data.detail
      ]);

      setStatus(res.data.status);
    } catch {
      setStatus("error");
    }
  };

  return (
    <div className="p-8 space-y-6">

      <h2 className="text-2xl font-bold text-white">
        Threat Simulation Lab
      </h2>

      <div className="flex gap-3">
        <button onClick={() => run("bitflip")} className="btn">Bit Flip</button>
        <button onClick={() => run("tag")} className="btn">Tag Corrupt</button>
        <button onClick={() => run("truncate")} className="btn">Truncate</button>
      </div>

      {/* STATUS */}
      {status === "DETECTED" && (
        <div className="bg-red-500/20 border border-red-500 p-4 rounded">
          <ShieldAlert className="text-red-400"/>
          <p className="text-red-400 font-bold">TAMPER DETECTED</p>
        </div>
      )}

      {status === "FAILED" && (
        <div className="bg-yellow-500/20 border border-yellow-500 p-4 rounded">
          Tamper NOT detected
        </div>
      )}

      {status === "running" && (
        <div className="text-blue-400">Running...</div>
      )}

      {/* LOGS */}
      <div className="text-xs font-mono text-gray-400">
        {logs.map((l, i) => <p key={i}>{l}</p>)}
      </div>

    </div>
  );
};

export default ThreatLab;
